function normalizeTimeOfDay(value:number):number{return((value%1)+1)%1;}
function smoothStep(value:number):number{const clamped=Math.max(0,Math.min(1,value));return clamped*clamped*(3-2*clamped);}
function dayCycleState(value:number):{phase:DayPhase;label:string;darkness:number;warmth:number}{
  const time=normalizeTimeOfDay(value);
  if(time>=.2&&time<.3){const progress=smoothStep((time-.2)/.1);return{phase:"dawn",label:"Dawn",darkness:.72*(1-progress),warmth:Math.sin(progress*Math.PI)};}
  if(time>=.3&&time<.72)return{phase:"day",label:"Day",darkness:0,warmth:0};
  if(time>=.72&&time<.82){const progress=smoothStep((time-.72)/.1);return{phase:"dusk",label:"Dusk",darkness:.72*progress,warmth:Math.sin(progress*Math.PI)};}
  return{phase:"night",label:"Night",darkness:.72,warmth:0};
}
function formatWorldClock(value:number):string{const totalMinutes=Math.floor(normalizeTimeOfDay(value)*24*60),hours=Math.floor(totalMinutes/60),minutes=totalMinutes%60;return`${hours.toString().padStart(2,"0")}:${minutes.toString().padStart(2,"0")}`;}
function isNightSpawn(enemy:Enemy):boolean{return enemy.id>=NIGHT_SPAWN_ID_BASE;}

function applyRadialDeadZone(input:Vec):Vec {
  const magnitude=Math.min(1,Math.hypot(input.x,input.y));
  if(magnitude<=JOYSTICK_DEAD_ZONE)return{x:0,y:0};
  const scaledMagnitude=(magnitude-JOYSTICK_DEAD_ZONE)/(1-JOYSTICK_DEAD_ZONE),scale=scaledMagnitude/magnitude;
  return{x:input.x*scale,y:input.y*scale};
}
