function roomLoot(room: number): LootChoice[] {
  const rarity: Rarity = room >= 5 ? "Legendary" : room >= 4 ? "Epic" : room >= 2 ? "Rare" : "Common";
  const weapon = ["Leechfang", "Graveglass", "Stormcleaver", "Crown Splitter", "Warden's Hunger"][Math.min(room - 1, 4)] ?? "Leechfang";
  const armor = ["Briar Mantle", "Cinderhide", "Graveplate", "Ashen Aegis", "Crucible Carapace"][Math.min(room - 1, 4)] ?? "Briar Mantle";
  const charm = ["Quickfang Rune", "Hunter's Eye", "Storm Sigil", "Warden's Mark", "Vault Magnet"][Math.min(room - 1, 4)] ?? "Quickfang Rune";
  return [
    { id:"weapon", name:weapon, rarity, icon:"✦", detail:`Lifesteal +${2+room}% · +${6+room*3} damage`, apply:(s)=>({...s,weaponName:weapon,weaponDamage:s.weaponDamage+6+room*3,lifesteal:Math.min(.5,s.lifesteal+.02+room*.01),rarity,level:s.level+1,hp:Math.min(s.maxHp,s.hp+20),items:[...s.items,weapon].slice(-60)}) },
    { id:"armor", name:armor, rarity, icon:"◆", detail:`Thorns +${4+room*2}% · +${4+room*2} armor`, apply:(s)=>({...s,armorName:armor,armorDefense:Math.min(60,s.armorDefense+4+room*2),thorns:Math.min(.75,s.thorns+.04+room*.02),maxHp:s.maxHp+10+room*3,hp:s.maxHp+10+room*3,level:s.level+1,items:[...s.items,armor].slice(-60)}) },
    { id:"charm", name:charm, rarity, icon:"◈", detail:`Dash -${8+room*2}% · pickup range · crit`, apply:(s)=>({...s,charmName:charm,attackSpeed:Math.min(3,s.attackSpeed+.12),critChance:Math.min(.5,s.critChance+.04),dashReduction:Math.min(.75,s.dashReduction+.08+room*.02),moveSpeed:Math.min(1,s.moveSpeed+.03),pickupRadius:Math.min(240,s.pickupRadius+18),hp:Math.min(s.maxHp,s.hp+20),level:s.level+1,items:[...s.items,charm].slice(-60)}) },
  ];
}

