type ObstacleKind = "tree" | "rock" | "building" | "fence" | "torch" | "npc" | "prop" | "vehicle";
type CircleObstacle = { shape:"circle"; x:number; y:number; r:number; kind:ObstacleKind };
type RectObstacle = { shape:"rect"; x:number; y:number; halfW:number; halfH:number; kind:ObstacleKind };
type Obstacle = CircleObstacle | RectObstacle;
function circleObstacle(x:number,y:number,r:number,kind:ObstacleKind):CircleObstacle{return{shape:"circle",x,y,r,kind};}
