type RenderDepthKind="house"|"stall"|"npc"|"rock"|"cliff"|"tree"|"enemy"|"dog"|"wolf"|"vehicle"|"player";
type RenderDepthItem={depth:number;kind:RenderDepthKind;source:object|null};
const renderDepthItems:RenderDepthItem[]=[],renderDepthPool:RenderDepthItem[]=[];
let renderViewCenterX=0,renderViewCenterY=0,renderViewHalfW=0,renderViewHalfH=0;
function isInRenderView(x:number,y:number,margin=DRAW_MARGIN):boolean{return Math.abs(x-renderViewCenterX)<renderViewHalfW+margin&&Math.abs(y-renderViewCenterY)<renderViewHalfH+margin;}
function pushRenderDepth(kind:RenderDepthKind,depth:number,source:object|null):void{const index=renderDepthItems.length,item=renderDepthPool[index]??{depth:0,kind:"player" as RenderDepthKind,source:null};if(index===renderDepthPool.length)renderDepthPool.push(item);item.depth=depth;item.kind=kind;item.source=source;renderDepthItems.push(item);}
function compareRenderDepth(a:RenderDepthItem,b:RenderDepthItem):number{return a.depth-b.depth;}
function npcById(id:NpcId):Npc|undefined{for(const npc of NPCS)if(npc.id===id)return npc;return undefined;}
function hasMountedVehicle(vehicles:Vehicle[]):boolean{for(const vehicle of vehicles)if(vehicle.mounted)return true;return false;}

